package tech.qiantong.qdata.acceptance;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.support.TransactionTemplate;
import tech.qiantong.qdata.common.core.domain.entity.SysUser;
import tech.qiantong.qdata.common.core.domain.model.LoginUser;
import tech.qiantong.qdata.module.da.api.service.DataResourceAccess;
import tech.qiantong.qdata.module.att.service.project.*;
import tech.qiantong.qdata.module.dpp.service.etl.*;
import tech.qiantong.qdata.module.dpp.controller.admin.etl.DppEtlTaskController;
import tech.qiantong.qdata.module.dpp.controller.admin.etl.vo.*;
import tech.qiantong.qdata.security.web.service.ProjectPermissionService;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@EnabledIfEnvironmentVariable(named="QDATA_NAMESPACE_INTEGRATION",matches="true")
class DevelopmentProjectCapabilityIntegrationTest {
    SingleConnectionDataSource fixture;JdbcTemplate jdbc;TransactionTemplate tx;
    ProjectPermissionService permissions;ProjectAuthority authority;ProjectCatalogAccess catalogs;DataResourceAccess membership;DevelopmentResourceAccess development;IDppEtlTaskService service;DppEtlTaskController controller;
    @BeforeEach void setup(){
        String url=System.getenv("QDATA_DEVELOPMENT_CAPABILITY_URL");assertNotNull(url);assertTrue(url.contains("/qdata_development_capability_"));fixture=new SingleConnectionDataSource(url,"root",System.getenv("QDATA_NAMESPACE_PASSWORD"),true);jdbc=new JdbcTemplate(fixture);tx=new TransactionTemplate(new DataSourceTransactionManager(fixture));
        var user=new SysUser();user.setUserId(926L);user.setUserName("fixture-multi-project");user.setRoles(List.of());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new LoginUser(926L,null,user,Set.of("*:*:*")),null,List.of()));
        permissions=new ProjectPermissionService(jdbc);authority=new ProjectAuthority(jdbc,permissions);catalogs=new ProjectCatalogAccess(jdbc,authority,permissions);membership=mock(DataResourceAccess.class);when(membership.visibleProjectIds()).thenAnswer(ignored->new HashSet<>(jdbc.queryForList("SELECT p.id FROM att_project p WHERE p.del_flag='0' AND p.valid_flag='1' AND (p.manager_id=926 OR EXISTS(SELECT 1 FROM att_project_user_rel r WHERE r.project_id=p.id AND r.user_id=926 AND r.del_flag='0' AND r.valid_flag='1'))",Long.class)));
        development=new DevelopmentResourceAccess(jdbc,membership,permissions);service=mock(IDppEtlTaskService.class);controller=new DppEtlTaskController();ReflectionTestUtils.setField(controller,"resourceAccess",development);ReflectionTestUtils.setField(controller,"dppEtlTaskService",service);
    }
    @AfterEach void finish(){SecurityContextHolder.clearContext();fixture.destroy();}
    String projectCode(long id){return jdbc.queryForObject("SELECT code FROM att_project WHERE id=?",String.class,id);}
    DppEtlNewNodeSaveReqVO draft(long project){var value=new DppEtlNewNodeSaveReqVO();value.setProjectId(project);value.setProjectCode(Long.valueOf(projectCode(project)));value.setType("3");value.setScheduler("QUARTZ");return value;}
    void revokeReader(){jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id=17 AND m.perms LIKE 'dpp:%'");}
    @Test void fixtureHasTwoProjectsDifferentCapabilitiesAndNoGlobalRole(){assertEquals(Set.of(143L,144L),membership.visibleProjectIds());assertTrue(permissions.has(144L,"dpp:developTask:edit"));assertFalse(permissions.has(143L,"dpp:developTask:edit"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM system_user_role ur JOIN system_role r ON r.role_id=ur.role_id WHERE ur.user_id=926 AND COALESCE(r.project_id,0)=0",Integer.class));assertFalse(permissions.isAdministrator());}
    @Test void taskReadsRemainAvailableInBothAuthorizedProjects(){assertEquals(Set.of(900001L,900002L),new HashSet<>(development.taskIds()));assertDoesNotThrow(()->development.task(900001L));assertDoesNotThrow(()->development.task(900002L));}
    @Test void writeExecuteAndRemoveCannotBorrowAnotherProjectsPermission(){for(String action:List.of("edit","execute","remove")){assertDoesNotThrow(()->development.task(900002L,action));assertThrows(AccessDeniedException.class,()->development.task(900001L,action));}}
    @Test void creationUsesDestinationProjectPermissions(){assertDoesNotThrow(()->development.request(draft(144),"add"));assertThrows(AccessDeniedException.class,()->development.request(draft(143),"add"));}
    @Test void changingProjectOrCodeCannotRetargetAnExistingTask(){var value=draft(144);value.setId("900001");assertThrows(AccessDeniedException.class,()->development.request(value,"edit"));value.setId("900002");value.setProjectCode(1L);assertThrows(AccessDeniedException.class,()->development.request(value,"edit"));}
    @Test void controllerExecutionStopsBeforeBusinessServiceForReadonlyProject(){assertThrows(AccessDeniedException.class,()->controller.startDppEtlTask(900001L));verifyNoInteractions(service);assertDoesNotThrow(()->controller.startDppEtlTask(900002L));verify(service).startDppEtlTask(900002L);}
    @Test void instanceExecutionInheritsParentTaskCapabilities(){assertDoesNotThrow(()->development.instance(900003L));assertThrows(AccessDeniedException.class,()->development.instance(900003L,"execute"));}
    @Test void revokingProjectReadHidesTaskAndHistoryDespiteBroadCachedPermissions(){tx.executeWithoutResult(status->{assertTrue(development.childIds(DevelopmentResourceAccess.Child.NODE).contains(900011L));assertTrue(development.childIds(DevelopmentResourceAccess.Child.NODE_LOG).contains(900012L));revokeReader();assertFalse(development.taskIds().contains(900001L));assertFalse(development.childIds(DevelopmentResourceAccess.Child.NODE).contains(900011L));assertFalse(development.childIds(DevelopmentResourceAccess.Child.NODE_LOG).contains(900012L));assertThrows(AccessDeniedException.class,()->development.task(900001L));status.setRollbackOnly();});}
    @Test void projectStatisticsCannotUseReadPermissionFromAnotherProject(){tx.executeWithoutResult(status->{revokeReader();assertDoesNotThrow(()->development.readType("3"));assertThrows(AccessDeniedException.class,()->controller.statistics(143L,projectCode(143),"3"));verifyNoInteractions(service);status.setRollbackOnly();});}
    @Test void integrationCapabilitiesDoNotBecomeDevelopmentCapabilities(){tx.executeWithoutResult(status->{jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id=900001 AND m.perms LIKE 'dpp:developTask:%'");assertDoesNotThrow(()->development.readType("1",144L));assertThrows(AccessDeniedException.class,()->development.readType("3",144L));assertFalse(development.taskIds().contains(900002L));status.setRollbackOnly();});}
    @Test void displayedActionsAreComputedForEachRowsOwnProject(){var read=new DppEtlTaskRespVO();read.setId(900001L);read.setProjectId(143L);read.setProjectCode(projectCode(143));read.setType("3");var write=new DppEtlTaskRespVO();write.setId(900002L);write.setProjectId(144L);write.setProjectCode(projectCode(144));write.setType("3");development.present(List.of(read,write));assertFalse(read.getCanEdit());assertFalse(read.getCanExecute());assertFalse(read.getCanRemove());assertTrue(write.getCanEdit());assertTrue(write.getCanExecute());assertTrue(write.getCanRemove());}
    @Test void capabilitiesEndpointRequiresTheRequestedProject(){assertThrows(AccessDeniedException.class,()->controller.capabilities(1L,projectCode(1),"3"));var reader=development.capabilities(143L,projectCode(143),"3");var writer=development.capabilities(144L,projectCode(144),"3");assertEquals(false,reader.get("canAdd"));assertEquals(true,writer.get("canAdd"));assertEquals(false,writer.get("canUseDolphin"));}
    @Test void localProjectCannotSubmitAnUnregisteredExternalSchedulerCode(){var value=draft(144);value.setScheduler("DOLPHINSCHEDULER");assertThrows(IllegalArgumentException.class,()->development.request(value,"add"));}
    @Test void taskCategoryMustBelongToItsProject(){var value=draft(144);value.setCatCode("900143");assertThrows(AccessDeniedException.class,()->development.request(value,"add"));value.setCatCode("900144");assertDoesNotThrow(()->development.request(value,"add"));}
    @Test void readableForeignNodeCodesCannotBeReusedByWriter(){assertDoesNotThrow(()->development.child(DevelopmentResourceAccess.Child.NODE,900011L));var value=draft(144);value.setTaskDefinitionList("[{\"code\":\"1789500000000011\"}]");assertThrows(AccessDeniedException.class,()->development.request(value,"add"));}
    @Test void readableForeignSubprocessCannotBeEmbeddedInAnotherProject(){var value=draft(144);value.setTaskDefinitionList("[{\"code\":\"1789500000000099\",\"taskParams\":{\"processDefinitionCode\":\"1789500000000001\"}}]");assertDoesNotThrow(()->development.task(900001L));assertThrows(AccessDeniedException.class,()->development.request(value,"add"));}
    @Test void categoryWritesAreCheckedAgainstCategoryProject(){for(var kind:ProjectCatalogAccess.Kind.values()){assertDoesNotThrow(()->catalogs.category(kind,900101L,"read"));assertThrows(AccessDeniedException.class,()->catalogs.category(kind,900101L,"edit"));assertDoesNotThrow(()->catalogs.category(kind,900102L,"edit"));assertThrows(AccessDeniedException.class,()->catalogs.projects(kind,"export",143L,projectCode(143)));assertEquals(List.of(144L),catalogs.projects(kind,"export",null,null));}}
    @Test void categoryCannotBeMovedAcrossProjectsOrIntoItself(){for(var kind:ProjectCatalogAccess.Kind.values()){assertThrows(AccessDeniedException.class,()->catalogs.prepare(kind,900102L,144L,projectCode(144),900101L,"900144","writer-root","edit"));assertThrows(IllegalArgumentException.class,()->catalogs.prepare(kind,900102L,144L,projectCode(144),900102L,"900144","writer-root","edit"));assertThrows(IllegalArgumentException.class,()->catalogs.prepare(kind,null,144L,projectCode(144),-1L,null,"invalid-parent","add"));assertThrows(AccessDeniedException.class,()->catalogs.prepare(kind,900101L,144L,projectCode(144),0L,"900143","reader-root","edit"));}}
    @Test void rootCategoryNamesAreUniqueWithinTheirProject(){for(var kind:ProjectCatalogAccess.Kind.values()){assertFalse(catalogs.nameUsed(kind,null,0L,"reader-root",144L,projectCode(144)));assertTrue(catalogs.nameUsed(kind,null,0L,"writer-root",144L,projectCode(144)));assertDoesNotThrow(()->catalogs.prepare(kind,null,144L,projectCode(144),0L,null,"reader-root","add"));assertThrows(IllegalArgumentException.class,()->catalogs.prepare(kind,null,144L,projectCode(144),0L,null,"writer-root","add"));}}
    @Test void categoryCodeAndProjectCodeCannotBeForged(){assertThrows(AccessDeniedException.class,()->catalogs.prepare(ProjectCatalogAccess.Kind.DEVELOP,900102L,144L,projectCode(143),0L,"900144","writer-root","edit"));assertThrows(AccessDeniedException.class,()->catalogs.prepare(ProjectCatalogAccess.Kind.DEVELOP,900102L,144L,projectCode(144),0L,"changed-code","writer-root","edit"));}
    @Test void categoryPaginationUsesServerAllowedProjects(){var config=new com.baomidou.mybatisplus.core.MybatisConfiguration();config.setEnvironment(new org.apache.ibatis.mapping.Environment("catalog-scope",new org.apache.ibatis.transaction.jdbc.JdbcTransactionFactory(),fixture));config.setMapUnderscoreToCamelCase(true);var pagination=new com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor();pagination.addInnerInterceptor(new com.baomidou.mybatisplus.extension.plugins.inner.PaginationInnerInterceptor(com.baomidou.mybatisplus.annotation.DbType.MYSQL));config.addInterceptor(pagination);config.addMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var sessions=new com.baomidou.mybatisplus.core.MybatisSqlSessionFactoryBuilder().build(config);try(var session=sessions.openSession()){var mapper=session.getMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var request=new tech.qiantong.qdata.module.att.controller.admin.cat.vo.AttDataDevCatPageReqVO();request.setPageSize(1);request.setAccessibleProjectIds(catalogs.projects(ProjectCatalogAccess.Kind.DEVELOP,"read",null,null));assertEquals(2,mapper.selectPage(request).getTotal());request.setAccessibleProjectIds(catalogs.projects(ProjectCatalogAccess.Kind.DEVELOP,"export",null,null));var page=mapper.selectPage(request);assertEquals(1,page.getTotal());assertEquals(144L,page.getRows().get(0).getProjectId());}}
    @Test void categoryServiceAllowsTheSameRootNameInDifferentProjects(){
        var config=new com.baomidou.mybatisplus.core.MybatisConfiguration();config.setEnvironment(new org.apache.ibatis.mapping.Environment("category-write",new org.mybatis.spring.transaction.SpringManagedTransactionFactory(),fixture));config.setMapUnderscoreToCamelCase(true);config.addMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var sessions=new com.baomidou.mybatisplus.core.MybatisSqlSessionFactoryBuilder().build(config);
        tx.executeWithoutResult(status->{try(var session=sessions.openSession()){var mapper=session.getMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var implementation=new tech.qiantong.qdata.module.att.service.cat.impl.AttDataDevCatServiceImpl();ReflectionTestUtils.setField(implementation,"baseMapper",mapper);ReflectionTestUtils.setField(implementation,"attDataDevCatMapper",mapper);var value=new tech.qiantong.qdata.module.att.controller.admin.cat.vo.AttDataDevCatSaveReqVO();value.setProjectId(144L);value.setProjectCode(projectCode(144));value.setParentId(0L);value.setName("reader-root");value.setCreateTime(new java.util.Date());value.setUpdateTime(new java.util.Date());value.setCreatorId(926L);value.setCreateBy("fixture");value.setValidFlag(true);Long id=implementation.createAttDataDevCat(value);assertNotNull(id);assertEquals(144L,mapper.selectById(id).getProjectId());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM att_data_dev_cat WHERE project_id=143 AND name='reader-root'",Integer.class));}status.setRollbackOnly();});
    }

    @Test void developmentOnlyReadersCanOpenTheCombinedTaskSelector(){tx.executeWithoutResult(status->{jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id IN(17,900001) AND m.perms LIKE 'dpp:%' AND m.perms NOT LIKE 'dpp:developTask:%'");jdbc.update("DELETE rm FROM system_role_menu rm JOIN system_menu m ON m.menu_id=rm.menu_id WHERE rm.role_id=900001 AND m.perms IN('att:taskCat:list','att:taskCat:query')");assertTrue(catalogs.projects(ProjectCatalogAccess.Kind.INTEGRATION,"read",144L,projectCode(144),true).isEmpty());var request=new DppEtlTaskPageReqVO();request.setProjectId(144L);request.setProjectCode(projectCode(144));assertDoesNotThrow(()->controller.getDppEtlTaskListTree(request));verify(service).getDppEtlTaskListTree(request);assertEquals(Set.of(900001L,900002L),new HashSet<>(request.getAccessibleTaskIds()));status.setRollbackOnly();});}
    @Test void internalCategorySelectorAlsoEnforcesTheRequestedProject(){
        var config=new com.baomidou.mybatisplus.core.MybatisConfiguration();config.setEnvironment(new org.apache.ibatis.mapping.Environment("internal-catalog",new org.apache.ibatis.transaction.jdbc.JdbcTransactionFactory(),fixture));config.setMapUnderscoreToCamelCase(true);com.baomidou.mybatisplus.core.toolkit.GlobalConfigUtils.getGlobalConfig(config).setSqlInjector(new com.github.yulichang.injector.MPJSqlInjector());config.addMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var sessions=new com.baomidou.mybatisplus.core.MybatisSqlSessionFactoryBuilder().build(config);try(var session=sessions.openSession()){var mapper=session.getMapper(tech.qiantong.qdata.module.att.dal.mapper.cat.AttDataDevCatMapper.class);var implementation=new tech.qiantong.qdata.module.att.service.cat.impl.AttDataDevCatServiceImpl();ReflectionTestUtils.setField(implementation,"baseMapper",mapper);ReflectionTestUtils.setField(implementation,"attDataDevCatMapper",mapper);ReflectionTestUtils.setField(implementation,"catalogs",catalogs);var request=new tech.qiantong.qdata.module.att.api.cat.dto.AttDataDevCatReqDTO();request.setProjectId(144L);request.setProjectCode(projectCode(144));var values=implementation.getAttDataDevCatApiList(request);assertEquals(1,values.size());assertEquals("writer-root",values.get(0).getName());request.setProjectId(1L);request.setProjectCode(projectCode(1));assertThrows(AccessDeniedException.class,()->implementation.getAttDataDevCatApiList(request));}
    }

}
